boolean verifySignature(PublicKey peersPublicKey,byte[] nonce,byte[] signature,ErrorMessageHandler errorMessageHandler){
  boolean result;
  try {
    result=Sig.verify(peersPublicKey,nonce,signature);
  }
 catch (  CryptoException e) {
    log.warn(e.toString());
    result=false;
  }
  if (!result) {
    final String msg="Signature of nonce is not correct. " + "peersPublicKey=" + peersPublicKey + ", nonce(hex)="+ Utilities.bytesAsHexString(nonce)+ ", signature="+ Utilities.bytesAsHexString(signature);
    log.warn(msg);
    errorMessageHandler.handleErrorMessage(msg);
  }
  return result;
}
